from math import exp
from itertools import product, permutations
# A directed three-node cycle; state 0 turns an edge off, state 1 turns it on.
# The two models use the same f_1, f_2, aggregation, noise and state law.
labels_a=(1,1,2)
labels_b=(1,2,2)

def message(edge,x):
 return 0.0 if edge==0 else 1.0+(1.0 if edge==1 else -1.0)*exp(x)

def aggregate(h):
 return h*h-2*h

def mean(x,s,labels):
 return tuple(x[j]+aggregate(message(labels[(j-1)%3] if s[(j-1)%3] else 0, x[(j-1)%3])) for j in range(3))

max_error=0.0
for x in product((-1.3,0.2,1.1),repeat=3):
 for s in product((0,1),repeat=3):
  a,b=mean(x,s,labels_a),mean(x,s,labels_b)
  max_error=max(max_error,max(abs(v-w) for v,w in zip(a,b)))
print('Largest conditional-mean difference in finite sanity check:',max_error)
print('A global nonzero-label permutation relates the assignments:',any(tuple(dict(zip((1,2),p))[e] for e in labels_a)==labels_b for p in permutations((1,2))))
print('Analytically: g(f_1(x)) = g(f_2(x)) = exp(2*x)-1; f_1 prime = exp(x), f_2 prime = -exp(x).')
print('g prime at f_1, f_2, and f_0 is respectively 2*exp(x), -2*exp(x), and -2, all nonzero.')
