import itertools, math, random
# Three senders on a directed cycle. State 0 enables the edge; state 1 disables it.
labels_a=((1,0),(1,0),(2,0))
labels_b=((1,0),(2,0),(2,0))

def f(e,x):
    return 0.0 if e==0 else x if e==1 else math.pi-x

def mean(x,s,labels):
    y=list(x)
    for i in range(3):
        j=(i+1)%3
        y[j]+=math.sin(f(labels[i][s[i]],x[i]))
    return y

rng=random.Random(0)
max_difference=0.0
for s in itertools.product(range(2),repeat=3):
    for _ in range(100):
        x=[rng.uniform(-5,5) for _ in range(3)]
        max_difference=max(max_difference,max(abs(a-b) for a,b in zip(mean(x,s,labels_a),mean(x,s,labels_b))))
matching_permutations=[]
for swap_types in [False,True]:
    pi={0:0,1:2 if swap_types else 1,2:1 if swap_types else 2}
    for swap_states in itertools.product([False,True],repeat=3):
        if all(labels_a[i][k]==pi[labels_b[i][1-k if swap_states[i] else k]] for i in range(3) for k in range(2)):
            matching_permutations.append((swap_types,swap_states))
print('Counterexample: maximum conditional-mean difference:',max_difference)
print('Global type and per-node state permutations matching labels:',matching_permutations)
print('Analytic identity: sin(pi-x)=sin(x); type derivatives are 0, 1, -1.')
