import math
import itertools

def sigmoid(x):
    return 1/(1+math.exp(-x))

def f(e, x):
    return 0.0 if e == 0 else sigmoid(x) if e == 1 else 2+2*sigmoid(x)

def g(h):
    return h if h <= 1 else 2-h if h <= 2 else (h-2)/2

labels_a = (1,1,2)
labels_b = (1,2,2)
max_difference = 0.0
for x in itertools.product((-2.0,0.0,1.0),repeat=3):
    for states in itertools.product((0,1),repeat=3):
        means_a = [g(f(labels_a[i] if states[i] else 0,x[i])) for i in range(3)]
        means_b = [g(f(labels_b[i] if states[i] else 0,x[i])) for i in range(3)]
        max_difference = max(max_difference,max(abs(a-b) for a,b in zip(means_a,means_b)))
print('Edge-type counterexample: same transition means, maximum numerical difference:',max_difference)
print('Global label permutation exists:',any(tuple(p[e-1] for e in labels_a)==labels_b for p in itertools.permutations((1,2))))
print('Here each of three sources has one child in a directed cycle; state 0 switches that edge off. Both positive edge types have distinct, everywhere nonzero derivatives, but g maps their messages to the same effective interaction.')
